private boolean isInlineable(Document.OutputSettings out) {
    // Check if the tag is inline and also handle special inline tags causing line breaks
    if (!tag.isInline() || isLineBreakTag()) 
        return false;

    // If tag is not the first effective tag or if it doesn't cause a line break and
    // the document outline setting is not relevant, allow inlining.
    return (parent() == null || parent().isBlock())
        && (!isEffectivelyFirst() || isLineBreakTag())
        && !(out.outline() && !isLineBreakTag());
}

// Helper function to determine if a tag is an inline tag that causes a line break
private boolean isLineBreakTag() {
    return tag.normalName().equals("br");
}

